// Rango: lunes 00:00 → domingo 23:59 de la semana ANTERIOR
const ahora = new Date();
const diaSemana = ahora.getDay(); // 0=dom, 1=lun ...
const lunesEsta = new Date(ahora);
lunesEsta.setDate(ahora.getDate() - (diaSemana === 0 ? 6 : diaSemana - 1));
lunesEsta.setHours(0, 0, 0, 0);

const lunesAnterior = new Date(lunesEsta);
lunesAnterior.setDate(lunesEsta.getDate() - 7);

const domingoAnterior = new Date(lunesEsta);
domingoAnterior.setDate(lunesEsta.getDate() - 1);
domingoAnterior.setHours(23, 59, 59, 999);

return [{
  json: {
    desde: lunesAnterior.toISOString(),
    hasta: domingoAnterior.toISOString(),
    semanaLabel: `Semana del ${lunesAnterior.toLocaleDateString('es', {day:'2-digit',month:'short'})} al ${domingoAnterior.toLocaleDateString('es', {day:'2-digit',month:'short', year:'numeric'})}`
  }
}];

const checklists = $input.first().json.checklists || [];
const anomalias  = $input.first().json.anomalias  || [];
const semana     = $input.first().json.semanaLabel || 'Semana';

const total    = checklists.length;
const ok       = checklists.filter(c => c.resultado_general === 'ok').length;
const revisar  = checklists.filter(c => c.resultado_general === 'revisar').length;
const critico  = checklists.filter(c => c.resultado_general === 'critico').length;
const cumplimiento = total ? Math.round((ok / total) * 100) : 0;

const anomAlta  = anomalias.filter(a => a.severidad === 'alta').length;
const anomMedia = anomalias.filter(a => a.severidad === 'media').length;
const anomBaja  = anomalias.filter(a => a.severidad === 'baja').length;
const resueltas = anomalias.filter(a => a.estado === 'resuelta').length;

const html = `<!DOCTYPE html>
<html lang='es'>
<head>
<meta charset='UTF-8'>
<style>
  body { font-family: Arial, sans-serif; color: #0F2621; max-width: 700px; margin: 0 auto; padding: 24px; }
  h1   { color: #1D9E75; font-size: 22px; margin-bottom: 4px; }
  h2   { font-size: 16px; border-bottom: 1px solid #C8DED9; padding-bottom: 8px; margin-top: 28px; }
  .stats { display: flex; gap: 12px; margin: 16px 0; }
  .stat  { flex: 1; background: #F0FAF6; border-radius: 8px; padding: 14px; text-align: center; }
  .stat-num { font-size: 28px; font-weight: 700; }
  .stat-lbl { font-size: 12px; color: #5A7A72; }
  table { width: 100%; border-collapse: collapse; font-size: 13px; }
  th    { background: #1D9E75; color: white; padding: 8px 10px; text-align: left; }
  td    { padding: 8px 10px; border-bottom: 1px solid #E2EFEB; }
  tr:hover td { background: #F0FAF6; }
  .badge { padding: 2px 8px; border-radius: 99px; font-size: 11px; font-weight: 600; }
  .ok      { background: #E1F5EE; color: #085041; }
  .revisar { background: #FEF9EC; color: #633806; }
  .critico { background: #FCEBEB; color: #501313; }
  .alta    { background: #FCEBEB; color: #501313; }
  .media   { background: #FEF9EC; color: #633806; }
  .baja    { background: #E1F5EE; color: #085041; }
  .footer  { margin-top: 32px; font-size: 11px; color: #8AADA6; text-align: center; }
</style>
</head>
<body>
<h1>📋 Reporte semanal de mantenimiento</h1>
<p style='color:#5A7A72'>${semana}</p>

<h2>Resumen general</h2>
<div class='stats'>
  <div class='stat'><div class='stat-num' style='color:#1D9E75'>${total}</div><div class='stat-lbl'>Checklists</div></div>
  <div class='stat'><div class='stat-num' style='color:#1D9E75'>${cumplimiento}%</div><div class='stat-lbl'>Cumplimiento OK</div></div>
  <div class='stat'><div class='stat-num' style='color:#E24B4A'>${anomalias.length}</div><div class='stat-lbl'>Anomalías</div></div>
  <div class='stat'><div class='stat-num' style='color:#1D9E75'>${resueltas}</div><div class='stat-lbl'>Resueltas</div></div>
</div>

<h2>Anomalías de la semana</h2>
<table>
  <tr><th>Máquina</th><th>Descripción</th><th>Severidad</th><th>Estado</th><th>Reportado por</th></tr>
  ${anomalias.map(a => `
  <tr>
    <td>${a.maquina?.nombre ?? '—'} (${a.maquina?.codigo ?? '—'})</td>
    <td style='max-width:200px'>${a.descripcion.slice(0, 80)}${a.descripcion.length > 80 ? '…' : ''}</td>
    <td><span class='badge ${a.severidad}'>${a.severidad.toUpperCase()}</span></td>
    <td><span class='badge ${a.estado === 'resuelta' ? 'ok' : a.estado === 'abierta' ? 'critico' : 'revisar'}'>${a.estado}</span></td>
    <td>${a.reportado_por_usuario?.nombre ?? '—'}</td>
  </tr>`).join('')}
</table>

<h2>Detalle de checklists</h2>
<table>
  <tr><th>Fecha</th><th>Máquina</th><th>Área</th><th>Turno</th><th>Operador</th><th>Resultado</th></tr>
  ${checklists.map(c => `
  <tr>
    <td>${new Date(c.fecha_hora).toLocaleDateString('es')}</td>
    <td>${c.maquina?.nombre ?? '—'}</td>
    <td>${c.maquina?.area ?? '—'}</td>
    <td>${c.turno?.tipo ?? '—'}</td>
    <td>${c.operador?.nombre ?? '—'}</td>
    <td><span class='badge ${c.resultado_general}'>${c.resultado_general.toUpperCase()}</span></td>
  </tr>`).join('')}
</table>

<div class='footer'>Generado automáticamente por Maple Mantenimiento · ${new Date().toLocaleString('es')}</div>
</body></html>`;

return [{ json: { html, semana, totalChecklists: total, totalAnomalias: anomalias.length, cumplimiento } }];
